import{_ as a,c as o,o as i,ag as s}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Opciones de privacidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/privacy-choices.md","filePath":"es/guide/privacy-choices.md","lastUpdated":1794112334000}'),r={name:"es/guide/privacy-choices.md"};function n(t,e,c,d,p,l){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="opciones-de-privacidad" tabindex="-1">Opciones de privacidad <a class="header-anchor" href="#opciones-de-privacidad" aria-label="Permalink to &quot;Opciones de privacidad&quot;">​</a></h1><p>Esta página describe cómo enviar solicitudes de privacidad a Nicasa y qué puedes esperar.</p><h2 id="para-que-sirve" tabindex="-1">Para qué sirve <a class="header-anchor" href="#para-que-sirve" aria-label="Permalink to &quot;Para qué sirve&quot;">​</a></h2><p>Utiliza esta página para solicitar acceso a datos personales, solicitar su eliminación, solicitar portabilidad u oponerte a determinados usos de datos (por ejemplo, solicitudes de «No vender» cuando corresponda).</p><p>Nota: actualmente Nicasa no recopila ni almacena datos personales (consulta la Política de privacidad). Si crees que tenemos datos personales sobre ti, envía una solicitud y lo investigaremos.</p><h2 id="como-enviar-una-solicitud" tabindex="-1">Cómo enviar una solicitud <a class="header-anchor" href="#como-enviar-una-solicitud" aria-label="Permalink to &quot;Cómo enviar una solicitud&quot;">​</a></h2><p>Proporciona la siguiente información al hacer una solicitud para ayudarnos a procesarla con eficacia:</p><ul><li>Tu nombre</li><li>Correo electrónico de contacto</li><li>Descripción de la solicitud (acceso, eliminación, portabilidad u oposición)</li><li>Cualquier identificador que nos ayude a localizar registros (por ejemplo, el ID de un ticket de soporte)</li></ul><p>Envía las solicitudes a uno de los siguientes canales:</p><ul><li>Correo electrónico: <a href="mailto:nicasa@w3cub.com" target="_blank" rel="noreferrer">nicasa@w3cub.com</a></li><li>Abrir una incidencia de privacidad: <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li></ul><h2 id="tiempo-de-respuesta" tabindex="-1">Tiempo de respuesta <a class="header-anchor" href="#tiempo-de-respuesta" aria-label="Permalink to &quot;Tiempo de respuesta&quot;">​</a></h2><p>Nuestro objetivo es acusar recibo y responder a las solicitudes válidas en un plazo de 30 días. Si necesitamos más tiempo, te lo notificaremos con un plazo estimado.</p><h2 id="si-no-disponemos-de-datos-personales" tabindex="-1">Si no disponemos de datos personales <a class="header-anchor" href="#si-no-disponemos-de-datos-personales" aria-label="Permalink to &quot;Si no disponemos de datos personales&quot;">​</a></h2><p>Dado que Nicasa está diseñada para procesar imágenes localmente y no recopilar datos de usuario, muchas solicitudes se cerrarán confirmando que no se dispone de datos personales. Si aportas pruebas de que se recopilaron datos personales, lo investigaremos y tomaremos las medidas oportunas.</p><h2 id="no-vender-oposicion" tabindex="-1">No vender / Oposición <a class="header-anchor" href="#no-vender-oposicion" aria-label="Permalink to &quot;No vender / Oposición&quot;">​</a></h2><p>Si estás ejerciendo un derecho de tu jurisdicción (por ejemplo, conforme a la CCPA/CPRA) para oponerte a la venta, y crees que hemos vendido tus datos personales, describe las circunstancias en tu solicitud. Si no vendemos datos personales, lo confirmaremos en nuestra respuesta.</p><h2 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to &quot;Contacto&quot;">​</a></h2><p>Si tienes preguntas sobre este proceso, escribe a <a href="mailto:nicasa@w3cub.com" target="_blank" rel="noreferrer">nicasa@w3cub.com</a> o abre una incidencia en <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a>.</p>',18)])])}const h=a(r,[["render",n]]);export{m as __pageData,h as default};
